import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(10))
G.add_edges_from([(8,9), (2,8), (2,7), (2,9), (0,1), (0,8), (1,8), (3,8), (5,8)])
while min(deg for node, deg in G.degree()) < 4:
    for u in range(10):
        for v in range(u+1, 10):
            if not G.has_edge(u, v):
                G.add_edge(u, v)
                if min(deg for node, deg in G.degree()) >= 4:
                    break
        else:
            continue
        break
print(G.edges())
